class Cart:
    def __init__(self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self.items = []  # list of (unit_price, quantity)
        self.discounts = []  # list of percent values
        self.vouchers = []  # list of fixed amounts

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        if quantity <= 0:
            raise ValueError("Quantity must be greater than zero")
        self.items.append((unit_price, quantity))

    def apply_discount(self, percent: float) -> None:
        self.discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        self.vouchers.append(amount)

    def total(self) -> float:
        items_total = sum(price * qty for price, qty in self.items)

        # Determine best single saving among discounts and vouchers
        best_saving = 0.0
        for percent in self.discounts:
            saving = items_total * (percent / 100.0)
            if saving > best_saving:
                best_saving = saving
        for amount in self.vouchers:
            saving = amount
            if saving > best_saving:
                best_saving = saving

        # Voucher/discount can't exceed items total
        if best_saving > items_total:
            best_saving = items_total

        discounted_total = items_total - best_saving

        # Shipping: free if discounted_total meets threshold
        if discounted_total >= self.free_shipping_threshold:
            shipping = 0.0
        else:
            shipping = self.shipping_cost

        return round(discounted_total + shipping, 2)
